"""Split documentation pages into retrievable chunks."""

import re
from typing import List

from pydantic import BaseModel, Field

from rasa.builder.document_retrieval.local.config import (
    ChunkingConfig,
    ChunkingStrategy,
)
from rasa.builder.document_retrieval.source import SourceDocument

# Rough English approximation used to convert token budgets to word counts,
# avoiding a tokenizer dependency.
TOKENS_PER_WORD = 0.75

# Matches markdown headings h1-h3 at the start of a line.
_HEADING_RE = re.compile(r"^#{1,3}\s+.*$", re.MULTILINE)


class Chunk(BaseModel):
    """A single retrievable chunk carrying its source-document provenance."""

    text: str
    doc_id: str
    url: str
    title: str
    topic: str
    version: str = Field(
        default="",
        description="Source document version/hash; used for incremental sync.",
    )
    chunk_index: int = Field(
        description="Sequential index of the chunk within the document."
    )


class Chunker:
    """Splits a :class:`SourceDocument` into :class:`Chunk` objects per a strategy."""

    def __init__(self, config: ChunkingConfig) -> None:
        self._config = config

    def chunk_document(self, document: SourceDocument, topic: str) -> List[Chunk]:
        """Split a document into chunks according to the configured strategy."""
        if self._config.strategy is ChunkingStrategy.WHOLE_PAGE:
            texts = [document.content]
        elif self._config.strategy is ChunkingStrategy.FIXED_TOKEN:
            texts = self._fixed_token(document.content)
        elif self._config.strategy is ChunkingStrategy.BY_HEADING:
            texts = self._by_heading(document.content, document.title)
        else:  # pragma: no cover - exhaustive over the enum
            raise ValueError(f"Unknown chunking strategy: {self._config.strategy}")

        return [
            Chunk(
                text=text,
                doc_id=document.id,
                url=document.url or "",
                title=document.title,
                topic=topic,
                version=document.version or "",
                chunk_index=i,
            )
            for i, text in enumerate(t for t in texts if t.strip())
        ]

    def _fixed_token(self, text: str) -> List[str]:
        """Sliding word-window split approximating a token budget."""
        words = text.split()
        if not words:
            return []
        per_chunk = max(1, round(self._config.chunk_size * TOKENS_PER_WORD))
        overlap = max(0, round(self._config.chunk_overlap * TOKENS_PER_WORD))
        step = max(1, per_chunk - overlap)
        return [" ".join(words[i : i + per_chunk]) for i in range(0, len(words), step)]

    def _by_heading(self, text: str, title: str) -> List[str]:
        """Split at h1-h3 boundaries, keeping the heading and page title in-chunk.

        Oversized sections fall back to the fixed-token splitter. Small-section
        merging is intentionally skipped (known refinement, not needed for POC).
        """
        matches = list(_HEADING_RE.finditer(text))

        sections: List[str] = []
        if not matches:
            sections.append(text.strip())
        else:
            if matches[0].start() > 0:  # preamble before the first heading
                sections.append(text[: matches[0].start()].strip())
            for i, m in enumerate(matches):
                end = matches[i + 1].start() if i + 1 < len(matches) else len(text)
                sections.append(text[m.start() : end].strip())

        max_words = round(self._config.chunk_size / TOKENS_PER_WORD)
        chunks: List[str] = []
        for section in filter(None, sections):
            if len(section.split()) > max_words:
                heading = section.splitlines()[0]
                for piece in self._fixed_token(section):
                    chunks.append(f"{title}\n{heading}\n{piece}")
            else:
                chunks.append(f"{title}\n{section}")
        return chunks
